public class PomCoordinateReader {

    public static String tagValue(String pom, String tag) {
        String open = "<" + tag + ">";
        String close = "</" + tag + ">";
        int start = pom.indexOf(open);
        if (start < 0) {
            return "";
        }
        int from = start + open.length();
        int end = pom.indexOf(close, from);
        if (end < 0) {
            return "";
        }
        return pom.substring(from, end).trim();
    }

    public static String coordinates(String pom) {
        String groupId = tagValue(pom, "groupId");
        String artifactId = tagValue(pom, "artifactId");
        String version = tagValue(pom, "version");
        if (groupId.isEmpty() || artifactId.isEmpty() || version.isEmpty()) {
            return "";
        }
        return groupId + ":" + artifactId + ":" + version;
    }
}
